# Generated by build.py from recipe.yml for recipe http-slow-down-one-path. Do not edit.
Set-Location $PSScriptRoot
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--fault', '"delay;stage=command;path=/slow;ms=5000"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -Z --parallel-immediate -m 2 -w "%{url.path} %{http_code} %{exitcode}\n" -o NUL http://127.0.0.1:8080/slow/report.txt -o NUL http://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
